import os
from mindee import Client, product, documents

def extract_receipt_fields(payload, config=None):
    config = config or {}
    api_key = config.get("api_key") or os.environ["MINDEE_API_KEY"]
    client = Client(api_key=api_key)
    input_doc = documents.image.ImageInput(file_object=payload)
    prediction = client.parse(product.ReceiptV5, input_doc).document.inference.prediction
    items = []
    for line in getattr(prediction, "line_items", []) or []:
        items.append({
            "description": getattr(line, "description", None),
            "quantity": getattr(line, "quantity", None),
            "unit_price": getattr(line, "unit_price", None),
            "total_price": getattr(line, "total_amount", None),
        })
    result = {
        "merchant": getattr(getattr(prediction, "supplier_name", None), "value", None),
        "tax": getattr(getattr(prediction, "total_tax", None), "value", None),
        "total": getattr(getattr(prediction, "total_amount", None), "value", None),
        "items": items,
    }
    return result
